<?php use App\Catalog; $new = $s === null; ?>
<div class="topbar"><div><a class="small" href="/admin/catalog">← Catalog</a><h1><?= $new ? 'New service' : e($s['name']) ?></h1></div></div>
<form class="panel" method="post" action="/admin/catalog/<?= $new ? 'new' : e($s['slug']) ?>" style="max-width:900px"><?= App\Csrf::field() ?>
  <div class="grid g2"><div class="field"><label for="nm">Name</label><input id="nm" name="name" type="text" value="<?= e($s['name'] ?? '') ?>" required></div><?php if ($new): ?><div class="field"><label for="sl">Slug</label><input id="sl" name="slug" type="text" required pattern="[a-z0-9_]+"></div><?php endif; ?></div>
  <div class="grid g3"><div class="field"><label for="ca">Category</label><select id="ca" name="category"><?php foreach (Catalog::CATEGORIES as $k => $n): ?><option value="<?= $k ?>"<?= ($s['category'] ?? '') === $k ? ' selected' : '' ?>><?= e($n) ?></option><?php endforeach; ?></select></div>
    <div class="field"><label for="pm">Pricing model</label><select id="pm" name="pricing_model"><?php foreach (['one_time', 'monthly', 'yearly', 'per_province', 'quote'] as $m): ?><option<?= ($s['pricing_model'] ?? '') === $m ? ' selected' : '' ?>><?= $m ?></option><?php endforeach; ?></select></div>
    <div class="field"><label for="st">Status</label><select id="st" name="status"><?php foreach (['active', 'hidden', 'retired'] as $m): ?><option<?= ($s['status'] ?? 'active') === $m ? ' selected' : '' ?>><?= $m ?></option><?php endforeach; ?></select></div></div>
  <div class="grid g3"><div class="field"><label for="pr">Price (CAD)</label><input id="pr" name="price" type="number" step="0.01" value="<?= isset($s['price_cents']) && $s['price_cents'] !== null ? number_format($s['price_cents'] / 100, 2, '.', '') : '' ?>"><div class="hint">For "quote", this is the "from" price (blank = no starting price).</div></div>
    <div class="field"><label for="se">Setup fee (CAD)</label><input id="se" name="setup" type="number" step="0.01" value="<?= isset($s['setup_cents']) ? number_format($s['setup_cents'] / 100, 2, '.', '') : '0' ?>"></div><div class="field"><label for="tl">Timeline</label><input id="tl" name="timeline" type="text" value="<?= e($s['timeline'] ?? '') ?>"></div></div>
  <fieldset class="field" style="border:1px solid var(--line);border-radius:10px;padding:12px"><legend class="small"><b>Province prices</b> (per_province only, blank = not offered)</legend><div class="grid g4"><?php foreach (Catalog::PROVINCES as $c => $n): $v = $s['province_prices'][$c] ?? null; ?><label class="small"><?= $c ?><input name="province_prices[<?= $c ?>]" type="number" step="0.01" value="<?= $v !== null ? number_format($v / 100, 2, '.', '') : '' ?>"></label><?php endforeach; ?></div></fieldset>
  <div class="field"><label for="su">Summary</label><input id="su" name="summary" type="text" value="<?= e($s['summary'] ?? '') ?>"></div>
  <div class="field"><label for="de">Description</label><textarea id="de" name="description"><?= e($s['description'] ?? '') ?></textarea></div>
  <div class="field"><label for="dl">Deliverables (one per line)</label><textarea id="dl" name="deliverables"><?= e(implode("\n", $s['deliverables'] ?? [])) ?></textarea></div>
  <div class="field"><label for="li">Limitations / terms note</label><textarea id="li" name="limitations" style="min-height:60px"><?= e($s['limitations'] ?? '') ?></textarea></div>
  <button class="btn btn-primary">Save service</button></form>
